float srgb_to_linear(float u)
{
    const float U = 0.04045;
    const float A = 12.92;
    const float C = 0.055;
    const float gamma = 2.4;
    if(u <= U)
        return u / A;
    else
        return pow((u+C)/(1.+C), gamma);
}

float linear_to_srgb(float v)
{
    const float V = 0.0031308;
    const float A = 12.92;
    const float C = 0.055;
    const float gamma = 2.4;
    if(v <= V)
        return A*v;
    else
        return (1. + C)*pow(v,1./gamma) - C;
}

vec3 srgb_to_linear(vec3 srgb)
{
    vec3 linRGB;
    linRGB.r = srgb_to_linear(srgb.r);
    linRGB.g = srgb_to_linear(srgb.g);
    linRGB.b = srgb_to_linear(srgb.b);
    return linRGB;
}

vec3 linear_to_srgb(vec3 linRGB)
{
    vec3 srgb;
    srgb.r = linear_to_srgb(linRGB.r);
    srgb.g = linear_to_srgb(linRGB.g);
    srgb.b = linear_to_srgb(linRGB.b);
    return srgb;
}

float luminance(vec3 linrgb)
{
    return linrgb.r * 0.2126 + linrgb.g * 0.7152 + linrgb.b * 0.0722;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec3 col = texture(iChannel0, uv.xy).xyz;

    bool doConversion = mod(iTime,2.) > 1.;


    if(uv.x < 0.05 && uv.y > 0.95)
    {
        vec3 indicatorCol = doConversion ? vec3(0,1,0) : vec3(1,0,0);
        fragColor = vec4(indicatorCol,1);
        return;
    }

    if(doConversion)
        col = srgb_to_linear(col);

    col = vec3(luminance(col));

    if(doConversion)
        col = linear_to_srgb(col);
    // Output to screen
    fragColor = vec4(col,1.0);
}
